/**
 * Shared reasoning-chip throttle for defaults and agentic delivery.
 * Callers write Slack first, then commit.
 */
import { truncateTypingStatus } from "./api.js";
import { firstNonEmptyLine } from "./assistant.js";
import { SLACK_TYPING_MIN_GROWTH, SLACK_TYPING_MIN_INTERVAL_MS } from "./constants.js";
export function nextReasoningChip(state, text, now) {
    const line = firstNonEmptyLine(text);
    if (line === undefined) {
        return undefined;
    }
    const status = truncateTypingStatus(line);
    const previous = state.lastReasoningTypingStatus;
    const grew = previous !== null &&
        status.startsWith(previous) &&
        status.length >= previous.length + SLACK_TYPING_MIN_GROWTH;
    const lastAt = state.lastReasoningTypingAtMs;
    if (!grew &&
        lastAt !== null &&
        now - lastAt >= 0 &&
        now - lastAt < SLACK_TYPING_MIN_INTERVAL_MS) {
        return undefined;
    }
    return status;
}
export function commitReasoningChip(state, status, now) {
    state.lastReasoningTypingAtMs = now;
    state.lastReasoningTypingStatus = status;
}
